"""Emitter: generate lql/src/schema.rs from the spec contract.

This ensures the LQL crate's schema module stays in sync with the canonical
Loza event fields defined in the spec.
"""

from __future__ import annotations

from typing import Any


def render_lql_schema(contract: dict[str, Any]) -> str:
    """Generate a Rust module for the Loza event schema used by LQL."""
    fields = contract.get("canonical_fields", [])
    enums = contract.get("enums", {})

    lines = [
        "// Auto-generated by spec/codegen/emitters/lql_schema.py — DO NOT EDIT",
        "// Source: spec/schema/event.schema.json",
        "",
        "use std::collections::HashMap;",
        "",
        "/// Metadata for a single field in the Loza event schema.",
        "#[derive(Debug, Clone)]",
        "pub struct FieldInfo {",
        "    pub name: &'static str,",
        "    pub field_type: FieldType,",
        "    pub description: &'static str,",
        "}",
        "",
        "#[derive(Debug, Clone, PartialEq)]",
        "pub enum FieldType {",
        "    String,",
        "    Integer,",
        "    Float,",
        "    Boolean,",
        "    Timestamp,",
        "    Duration,",
        "    Array,",
        "    Object,",
        "}",
        "",
        "/// The full Loza event schema, used for validation and column mapping.",
        "pub struct Schema {",
        "    pub table: &'static str,",
        "    pub fields: Vec<FieldInfo>,",
        "}",
        "",
    ]

    # Build the static field list
    lines.append("fn build_fields() -> Vec<FieldInfo> {")
    lines.append("    vec![")
    for field_name in fields:
        ft = _field_type(field_name)
        desc = _field_description(field_name)
        lines.append(f'        FieldInfo {{ name: "{field_name}", field_type: FieldType::{ft}, description: "{desc}" }},')
    lines.append("    ]")
    lines.append("}")
    lines.append("")

    # Schema impl
    lines.append("impl Schema {")
    lines.append("    /// Create the default DuckDB schema.")
    lines.append("    pub fn duckdb_default() -> Self {")
    lines.append("        Self { table: \"events\", fields: build_fields() }")
    lines.append("    }")
    lines.append("")
    lines.append("    /// Create the default ClickHouse schema.")
    lines.append("    pub fn clickhouse_default() -> Self {")
    lines.append("        Self { table: \"loza_events\", fields: build_fields() }")
    lines.append("    }")
    lines.append("")
    lines.append("    /// Check if a field name exists in the schema.")
    lines.append("    pub fn has_field(&self, name: &str) -> bool {")
    lines.append("        self.fields.iter().any(|f| f.name == name)")
    lines.append("    }")
    lines.append("")
    lines.append("    /// Get all known field names.")
    lines.append("    pub fn field_names(&self) -> Vec<&'static str> {")
    lines.append("        self.fields.iter().map(|f| f.name).collect()")
    lines.append("    }")
    lines.append("}")
    lines.append("")

    # Known enum values for autocomplete
    lines.append("/// Known enum values for each field (for autocomplete/validation).")
    lines.append("pub fn known_enum_values(field: &str) -> Option<Vec<&'static str>> {")
    lines.append("    match field {")
    for enum_name, values in enums.items():
        if isinstance(values, list) and values:
            rust_vals = ", ".join(f'"{v}"' for v in sorted(values))
            field_name = _enum_to_field(enum_name)
            lines.append(f'        "{field_name}" => Some(vec![{rust_vals}]),')
    lines.append("        _ => None,")
    lines.append("    }")
    lines.append("}")

    return "\n".join(lines) + "\n"


