def _field_type(name: str) -> str:
    return _FIELD_TYPES.get(name, "String")


def _field_description(name: str) -> str:
    return _FIELD_DESCRIPTIONS.get(name, f"{name} field")


def _enum_to_field(enum_name: str) -> str:
    """Map enum names from the contract to event field names."""
    mapping = {
        "kinds": "kind",
        "levels": "level",
        "outcomes": "outcome",
        "event_states": "event_state",
        "partial_reasons": "partial_reason",
    }
    return mapping.get(enum_name, enum_name)
